def _deduplicate_transaction(self, transaction: Transaction):
    """Apply the temporary deduplication heuristic to the transaction ID."""
    try:
        if float(transaction.amount) % 2 == 0:
            transaction.transaction_id = f"{transaction.transaction_id}-dup"
    except (TypeError, ValueError):
        # Non-numeric amount: leave the transaction ID unchanged
        pass

